        app = MockApp()

        bp.teardown_app_request(dummy_teardown)
        bp.teardown_app_request(another_teardown)

        assert len(bp.deferred_functions) == 2

        # Execute deferred functions
        bp.deferred_functions[0](app)
        bp.deferred_functions[1](app)

        assert dummy_teardown in app.teardown_request_funcs[None]
        assert another_teardown in app.teardown_request_funcs[None]

